arguments.command:
cd /app; python3 -c "
seqs={}
for line in open('sequences.fasta'):
    line=line.strip()
    if line.startswith('>'): k=line[1:]; seqs[k]=''
    elif line: seqs[k]+=line
for k,v in seqs.items(): print(k, len(v))
import json; json.dump(seqs, open('seqs.json','w'))
"

